import hashlib
import os
from collections import defaultdict

def get_file_hash(filepath):
    hasher = hashlib.sha256()
    try:
        with open(filepath, 'rb') as f:
            while chunk := f.read(8192):
                hasher.update(chunk)
        return hasher.hexdigest()
    except Exception:
        return None

def find_duplicates(root_dir):
    hashes = defaultdict(list)

    for root, _, files in os.walk(root_dir):
        for filename in files:
            full_path = os.path.join(root, filename)
            # Root dizinine göre göreli yol al
            rel_path = os.path.relpath(full_path, root_dir).replace(os.sep, '/')

            file_hash = get_file_hash(full_path)
            if file_hash:
                hashes[file_hash].append(rel_path)

    # 2'den fazla dosyası olanları filtrele ve grupları kendi içinde sırala
    duplicate_groups = []
    for group in hashes.values():
        if len(group) > 1:
            duplicate_groups.append(sorted(group))

    # Grupları ilk dosya adına göre sırala
    duplicate_groups.sort(key=lambda x: x[0])
    return duplicate_groups

# Çalıştır ve sonucu kontrol et
groups = find_duplicates('dosyalar')
print("Doğrulandı:")
for g in groups:
    print(" | ".join(g))

