import hashlib
import os
from collections import defaultdict

def get_file_hash(filepath):
    """Dosyanın SHA256 özetini döndürür."""
    hasher = hashlib.sha256()
    try:
        with open(filepath, 'rb') as f:
            while chunk := f.read(8192):
                hasher.update(chunk)
        return hasher.hexdigest()
    except Exception:
        return None

def find_duplicates(root_dir):
    """İçeriği aynı olan dosyaları bulur ve gruplar."""
    hashes = defaultdict(list)

    for root, _, files in os.walk(root_dir):
        for filename in files:
            full_path = os.path.join(root, filename)
            # Göreceli yolu al (dosyalar/ klasörüne göre)
            rel_path = os.path.relpath(full_path, root_dir).replace(os.sep, '/')

            file_hash = get_file_hash(full_path)
            if file_hash:
                hashes[file_hash].append(rel_path)

    # Sadece 2 veya daha fazla dosyası olanları al ve içlerini sırala
    duplicate_groups = [sorted(group) for group in hashes.values() if len(group) > 1]

    # Grupları ilk dosya yoluna göre alfabetik sırala
    duplicate_groups.sort(key=lambda x: x[0])
    return duplicate_groups

def main():
    input_dir = 'dosyalar'
    output_file = 'kopyalar.txt'

    if not os.path.exists(input_dir):
        print(f"Hata: {input_dir} klasörü bulunamadı.")
        return

    duplicate_groups = find_duplicates(input_dir)

    with open(output_file, 'w', encoding='utf-8') as f:
        for group in duplicate_groups:
            f.write(" | ".join(group) + "\n")

    print(f"İşlem tamamlandı. {len(duplicate_groups)} grup bulundu.")
    print(f"Sonuçlar '{output_file}' dosyasına yazıldı.")

if __name__ == "__main__":
    main()

